// Geometry-only donor balancing and mapped-FD amplification probe.
#define main transition_localization_reference_not_invoked
#include "diagnose_transition_jets.cpp"
#undef main
#include "transition_background_projection.hpp"
#include "transition_orthogonal_background_jet.hpp"
using J=cubed_sphere::Jet;using Original=h::TransitionBackgroundJet;using Orth=h::TransitionOrthogonalBackgroundJet;
Real Scale(const Grid&g,size_t p){Real maxrow=0;for(int A=0;A<3;++A){Real sum=0;for(int a=0;a<3;++a)sum+=g.geometry[p].J[A][a]*g.geometry[p].J[A][a];maxrow=std::max(maxrow,std::sqrt(sum));}return 1/(g.n*maxrow);}
J SinJet(const J&a){J b(std::sin(a.f));for(int i=0;i<3;++i){b.d[i]=std::cos(a.f)*a.d[i];for(int j=0;j<3;++j)b.h[i][j]=std::cos(a.f)*a.h[i][j]-std::sin(a.f)*a.d[i]*a.d[j];}return b;}
J Delta(int mode,const Point&x){J y[3];for(int a=0;a<3;++a)y[a]=J::Variable(x[a],a);if(mode==0)return J(1);if(mode==1)return y[0]+J(.3)*y[1]-J(.7)*y[2]+y[0]*y[0]+J(.7)*y[0]*y[1]+J(2)*y[2]*y[2];if(mode==2||mode==3)return J(0);if(mode==4)return J(.001)*SinJet(J(3)*y[0])*SinJet(J(2)*y[1])+J(.001)*y[2]*y[2]*y[2];if(mode==5)return J(.001)*y[0]*y[1]/(y[0]*y[0]+y[1]*y[1]+y[2]*y[2]);if(mode==6)return J(.1)*SinJet(J(12)*y[0]+J(7)*y[1]-J(5)*y[2]);return J(.2)*cubed_sphere::Log(cubed_sphere::Power(y[0]*y[0]+y[1]*y[1]+y[2]*y[2],.5)+J(.17));}
Real Coefficient(int mode){return mode<2?0:(mode==3?.7:1);}
std::array<Real,24> PhysicalQuantities(U u,const Point&x){const auto omega=h::CompositeOmegaAt(x.data(),u);const auto c=h::EvolvedConstraints(u,omega);const auto p=h::ConformalRHS(u,omega,Real(4),Real(-.99),true);h::Z4cRHS<Real> rhs{};if(!c.valid||!h::AssembleInterior(p,omega.omega,rhs))throw std::runtime_error("invalid independent initial source");std::array<Real,24> out{};out[0]=c.hamiltonian;out[1]=std::sqrt(c.momentum_conformal_norm2);out[2]=rhs.chi;out[3]=rhs.trace;out[4]=rhs.theta;out[5]=h::WormholeLapseRate(x.data(),u);for(int t=0;t<6;++t){out[6+t]=rhs.metric[Engine::tensor_i[t]][Engine::tensor_j[t]];out[12+t]=rhs.a[Engine::tensor_i[t]][Engine::tensor_j[t]];}for(int i=0;i<3;++i){out[18+i]=rhs.lambda[i];out[21+i]=.005/.02*h::ReferenceTelegraphSupport(Radius(x.data()),.8,.24).value*u.alpha.d[i];}for(Real v:out)if(!std::isfinite(v))throw std::runtime_error("nonfinite full initial source");return out;}

struct Audit {Real value=0,gradient=0,hessian=0,coefficient=0;std::vector<std::array<Real,10>> weights;};
template<class Plan>Audit FunctionalAudit(const Plan&plan,int count,Real h,const h::PuncturePosition&point){Audit a;Real g[3]{},dd[3][3]{};for(int i=0;i<count;++i){V impulse(count,0);impulse[i]=1;typename Plan::Result r;if(!plan.Evaluate(impulse,point,r))throw std::runtime_error("basis impulse");std::array<Real,10>w{};w[0]=r.fitted_value;a.value+=std::abs(w[0]);a.coefficient+=std::abs(r.enrichment_coefficient);for(int d=0;d<3;++d){w[1+d]=h*r.gradient[d];g[d]+=std::abs(w[1+d]);}int row=4;for(int d=0;d<3;++d)for(int e=d;e<3;++e,++row){w[row]=h*h*r.hessian[d][e];dd[d][e]+=std::abs(w[row]);}a.weights.push_back(w);}for(int d=0;d<3;++d){a.gradient=std::max(a.gradient,g[d]);for(int e=d;e<3;++e)a.hessian=std::max(a.hessian,dd[d][e]);}return a;}
template<class Plan>S Evaluate(const Plan&plan,const V&v,Real value,const h::PuncturePosition&p,Real &coefficient){typename Plan::Result r;if(!plan.Evaluate(v,p,r))throw std::runtime_error("basis field");S q{};q.value=value;coefficient=r.enrichment_coefficient;for(int a=0;a<3;++a){q.d[a]=r.gradient[a];for(int b=0;b<3;++b)q.dd[a][b]=r.hessian[a][b];}return q;}
bool Safe(const Audit&a,Real reproduction){return a.value<=16&&a.gradient<=32&&a.hessian<=64&&a.coefficient<=10000&&reproduction<=1e-10;}
struct BackgroundTable {std::array<std::vector<Real>,2> values;std::array<std::vector<S>,2> jets;};
BackgroundTable Read192(const std::string&path,const Grid&grid){std::ifstream f(path);std::string magic;size_t count;int order;f>>magic>>count>>order;if(magic!="BACKGROUND_LOG_JETS_V1"||count!=grid.active.size()||order!=192)throw std::runtime_error("independent B192 table layout");BackgroundTable out;for(int field=0;field<2;++field){out.values[field].resize(count);out.jets[field].resize(count);}for(size_t p=0;p<count;++p){size_t id;Real r;f>>id>>r;if(id!=p||std::abs(r-Radius(grid.geometry[p].x))>2e-13)throw std::runtime_error("B192 coordinate mismatch");for(int field=0;field<2;++field){Real value,d,dd;f>>value>>d>>dd;out.values[field][p]=value;out.jets[field][p]=Radial(grid.geometry[p].x,value,d,dd);}}if(!f)throw std::runtime_error("B192 truncated");return out;}
struct Prepared {Orth plan;h::TransitionBackgroundProjection projection;Audit audit;std::vector<size_t>donors;std::string status="unbuilt";};
bool BuildPrepared(Prepared&out,const Grid&grid,size_t p,int count,const std::vector<std::pair<Real,size_t>>&nearest,const V&bg,const S&query,int field,int variant=0){const auto&x=grid.geometry[p].x;const Point at{x[0],x[1],x[2]};const Real h=Scale(grid,p);std::vector<Orth::Point>nodes;V values;for(int i=0;i<count;++i){const size_t id=nearest[i].second;out.donors.push_back(id);const auto&y=grid.geometry[id].x;nodes.push_back({y[0],y[1],y[2]});values.push_back(bg[id]+(variant==2?1e-12*std::sin(1.7*(id+1)+field):0));}S q=query;if(variant==3){q.value+=1e-12*std::sin(p+1);for(int a=0;a<3;++a){q.d[a]+=1e-12/h*std::sin((p+1)*(a+1));for(int b=0;b<3;++b)q.dd[a][b]+=1e-12/(h*h)*std::cos((p+3)*(a+b+1));}}if(!out.projection.Build(at,nodes,values,q,h)){out.status=out.projection.status;return false;}Orth::Options options;options.maximum_condition=1e8;options.maximum_scaled_weight_l1=1e6;if(!out.plan.Build(at,nodes,out.projection.residual,out.projection.query,h,h::PuncturePosition{},options)){out.status=out.plan.diagnostics().status;return false;}out.audit=FunctionalAudit(out.plan,count,h,h::PuncturePosition{});const auto&d=out.plan.diagnostics();if(!(out.audit.value<=16&&out.audit.gradient<=32&&out.audit.hessian<=64)){out.status="physical_amplification";return false;}if(!(d.reproduction<=1e-10)){out.status="reproduction";return false;}out.status="ready";return true;}
std::vector<size_t> InterfaceTargets(const Grid&g,const std::string&mode,int face){std::vector<size_t>out;for(size_t p=0;p<g.active.size();++p){const int block=p/216,i=p%6,j=p/6%6,k=p/36%6;const auto&b=g.mesh.blocks[block];if(b.face<0||b.layer!=0||i>=2)continue;if(mode=="face"&&b.face!=face)continue;if(mode=="preflight"&&!((j==0&&k==0)||(j==3&&k==3)||(j==0&&k==3)))continue;out.push_back(p);}if(mode=="face"&&out.size()!=72||mode=="preflight"&&out.size()!=36||mode=="all"&&out.size()!=432)throw std::runtime_error("predeclared interface count mismatch");return out;}
std::vector<std::pair<Real,size_t>> GlobalNearest(const Grid&g,size_t p){std::vector<std::pair<Real,size_t>>near;const auto&x=g.geometry[p].x;for(size_t q=0;q<g.active.size();++q){Real distance=0;for(int a=0;a<3;++a)distance+=std::pow(g.geometry[q].x[a]-x[a],2);near.push_back({distance,q});}std::partial_sort(near.begin(),near.begin()+256,near.end());return near;}
S TruthLog(const S&bg,int mode,const Point&x){const auto perturb=Delta(mode,x);const Real c=Coefficient(mode);S q{};q.value=c*bg.value+perturb.f;for(int a=0;a<3;++a){q.d[a]=c*bg.d[a]+perturb.d[a];for(int b=0;b<3;++b)q.dd[a][b]=c*bg.dd[a][b]+perturb.h[a][b];}return q;}
std::array<Real,24> FromLog(const S&q,int field,const U&initial,const Point&x){S physical{};if(Chart(x.data(),field).Reconstruct(q,physical)!=h::PositiveFieldStatus::valid)throw std::runtime_error("qualified positive reconstruction");auto u=initial;if(field==0)u.chi=physical;else u.alpha=physical;return PhysicalQuantities(u,x);}
std::array<Real,3> SingularValues(const cubed_sphere::Point&g){Real a[3][3]{};for(int i=0;i<3;++i)for(int j=0;j<3;++j)for(int k=0;k<3;++k)a[i][j]+=g.J[i][k]*g.J[j][k];for(int iteration=0;iteration<50;++iteration){int p=0,q=1;for(int i=0;i<3;++i)for(int j=i+1;j<3;++j)if(std::abs(a[i][j])>std::abs(a[p][q])){p=i;q=j;}if(std::abs(a[p][q])<1e-14*(a[0][0]+a[1][1]+a[2][2]))break;const Real angle=.5*std::atan2(2*a[p][q],a[q][q]-a[p][p]),c=std::cos(angle),s=std::sin(angle);const Real pp=c*c*a[p][p]-2*c*s*a[p][q]+s*s*a[q][q],qq=s*s*a[p][p]+2*c*s*a[p][q]+c*c*a[q][q];for(int k=0;k<3;++k)if(k!=p&&k!=q){const Real x=c*a[k][p]-s*a[k][q],y=s*a[k][p]+c*a[k][q];a[k][p]=a[p][k]=x;a[k][q]=a[q][k]=y;}a[p][p]=pp;a[q][q]=qq;a[p][q]=a[q][p]=0;}std::array<Real,3>out{std::sqrt(a[0][0]),std::sqrt(a[1][1]),std::sqrt(a[2][2])};std::sort(out.begin(),out.end());return out;}
std::vector<std::pair<Real,size_t>> MetricNearest(const Grid&g,size_t p,Real lambda){std::vector<std::pair<Real,size_t>>near;const auto&x=g.geometry[p].x;const Real h=Scale(g,p);for(size_t q=0;q<g.active.size();++q){Real delta[3],euclidean=0,mapped=0;for(int a=0;a<3;++a){delta[a]=g.geometry[q].x[a]-x[a];euclidean+=delta[a]*delta[a]/(h*h);}for(int A=0;A<3;++A){Real d=0;for(int a=0;a<3;++a)d+=g.n*g.geometry[p].J[A][a]*delta[a];mapped+=d*d;}near.push_back({(1-lambda)*euclidean+lambda*mapped,q});}std::partial_sort(near.begin(),near.begin()+256,near.end());return near;}
std::array<Real,2> WeightNorm(const std::map<int,std::array<Real,9>>&weights){Real grad[3]{},hess[6]{};for(const auto&entry:weights){for(int a=0;a<3;++a)grad[a]+=std::abs(entry.second[a]);for(int a=0;a<6;++a)hess[a]+=std::abs(entry.second[3+a]);}return {*std::max_element(grad,grad+3),*std::max_element(hess,hess+6)};}
void MappedFDAudit(const Grid&g,size_t p){const Real h=Scale(g,p);const auto singular=SingularValues(g.geometry[p]);std::map<int,std::array<Real,9>>raw,composed;V values(g.count,0);for(int index:Stencil(g,p)){values[index]=1;Real d[3],dd[3][3];g.Derivatives(values,0,p,d,dd);values[index]=0;auto&w=raw[index];for(int a=0;a<3;++a)w[a]=h*d[a];int row=3;for(int a=0;a<3;++a)for(int b=a;b<3;++b)w[row++]=h*h*dd[a][b];}
 std::vector<int>reverse(g.count,-1);for(size_t q=0;q<g.active.size();++q)reverse[g.active[q]]=q;std::map<int,const Grid::Row*>halos;for(const auto&row:g.halos)halos[row.target]=&row;size_t ghosts=0,boundary=0;for(const auto&entry:raw){if(reverse[entry.first]>=0){auto&w=composed[reverse[entry.first]];for(int f=0;f<9;++f)w[f]+=entry.second[f];}else{++ghosts;const auto&row=*halos.at(entry.first);Real sum=0;for(const auto&donor:row.entries){sum+=donor.weight;auto&w=composed[reverse[donor.point]];for(int f=0;f<9;++f)w[f]+=entry.second[f]*donor.weight;}auto&anchor=composed[reverse[row.entries[0].point]];for(int f=0;f<9;++f)anchor[f]+=entry.second[f]*(1-sum-row.boundary_weight);if(row.boundary_weight){++boundary;auto&w=composed[-1];for(int f=0;f<9;++f)w[f]+=entry.second[f]*row.boundary_weight;}}}const auto r=WeightNorm(raw),c=WeightNorm(composed);std::cout<<"{\"phase\":\"mapped_FD_amplification\",\"point\":"<<p<<",\"h_row_norm\":"<<h<<",\"inverse_J_singular_values\":["<<singular[0]<<','<<singular[1]<<','<<singular[2]<<"],\"physical_cell_singular_lengths\":["<<1/(g.n*singular[2])<<','<<1/(g.n*singular[1])<<','<<1/(g.n*singular[0])<<"],\"Jacobian_anisotropy\":"<<singular[2]/singular[0]<<",\"raw_padded_gradient_l1\":"<<r[0]<<",\"raw_padded_hessian_l1\":"<<r[1]<<",\"composed_active_gradient_l1\":"<<c[0]<<",\"composed_active_hessian_l1\":"<<c[1]<<",\"ghost_points\":"<<ghosts<<",\"physical_boundary_terms\":"<<boundary<<",\"same_physical_normalization_as_P5_caps\":true}\n";}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc!=3)throw std::runtime_error("initial exact");auto grid=MakeGrid();const auto initial=ReadInitial(argv[1],grid);const auto exact=ReadExact(argv[2]);BackgroundTable bg;for(int f=0;f<2;++f){bg.values[f].resize(initial.size());bg.jets[f].resize(initial.size());for(size_t p=0;p<initial.size();++p){bg.values[f][p]=f==0?std::log(initial[p].chi):std::log(initial[p].alpha)-std::log((1+initial[p].r*initial[p].r)/2);bg.jets[f][p]=StoredExact(grid.geometry[p].x,exact.at({0,p}),f);}}
 std::cout<<std::setprecision(17);for(size_t p:{size_t(0),size_t(1),size_t(126),size_t(127)}){MappedFDAudit(grid,p);const auto&xx=grid.geometry[p].x;const Point x{xx[0],xx[1],xx[2]};const auto u=Analytic(x,exact.at({0,p}));const Real h=Scale(grid,p);for(Real lambda:{0.,.5,1.}){const auto near=MetricNearest(grid,p,lambda);for(int field=0;field<2;++field)for(int count:{125,175,256}){Prepared plan;const bool valid=BuildPrepared(plan,grid,p,count,near,bg.values[field],bg.jets[field][p],field);Real minr=1e9,maxr=0,distance=0;for(size_t q:plan.donors){minr=std::min(minr,initial[q].r);maxr=std::max(maxr,initial[q].r);Real d=0;for(int a=0;a<3;++a)d+=std::pow(grid.geometry[q].x[a]-x[a],2);distance=std::max(distance,std::sqrt(d));}std::cout<<"{\"phase\":\"plan\",\"point\":"<<p<<",\"metric_lambda\":"<<lambda<<",\"field\":"<<field<<",\"donors\":"<<count<<",\"status\":\""<<plan.status<<"\",\"P5_rank\":"<<plan.projection.rank<<",\"condition\":"<<plan.plan.diagnostics().condition<<",\"reproduction\":"<<plan.plan.diagnostics().reproduction<<",\"gradient_l1\":"<<plan.audit.gradient<<",\"hessian_l1\":"<<plan.audit.hessian<<",\"physical_donor_radius_max\":"<<distance<<",\"donor_r_min\":"<<minr<<",\"donor_r_max\":"<<maxr<<"}\n";if(!valid)continue;
 for(int mode=0;mode<8;++mode){V values;for(size_t q:plan.donors){const auto&y=grid.geometry[q].x;values.push_back(Coefficient(mode)*bg.values[field][q]+Delta(mode,{y[0],y[1],y[2]}).f);}const auto truth=TruthLog(bg.jets[field][p],mode,x);Real coefficient;const auto fitted=Evaluate(plan.plan,values,truth.value,h::PuncturePosition{},coefficient);const auto actual=FromLog(fitted,field,u,x),expected=FromLog(truth,field,u,x);Real sourceerror=0;for(int f=2;f<24;++f)sourceerror=std::max(sourceerror,std::abs(actual[f]-expected[f]));V noise=values;for(size_t i=0;i<noise.size();++i)noise[i]+=1e-12*(std::sin(1.7*i)+std::cos(.9*i))/2;Real nc;const auto perturbed=Evaluate(plan.plan,noise,truth.value,h::PuncturePosition{},nc);Real change=0;for(int a=0;a<3;++a){change=std::max(change,h*std::abs(perturbed.d[a]-fitted.d[a]));for(int b=0;b<3;++b)change=std::max(change,h*h*std::abs(perturbed.dd[a][b]-fitted.dd[a][b]));}if(change>std::max(plan.audit.gradient,plan.audit.hessian)*1e-12+2e-13)throw std::runtime_error("balanced support noise bound");std::cout<<"{\"phase\":\"MMS\",\"point\":"<<p<<",\"metric_lambda\":"<<lambda<<",\"field\":"<<field<<",\"donors\":"<<count<<",\"mode\":"<<mode<<",\"H_error\":"<<actual[0]-expected[0]<<",\"source_error_max\":"<<sourceerror<<",\"scaled_noise\":"<<change<<"}\n";}
 }}}std::cout<<"{\"phase\":\"summary\",\"queries\":4,\"plans\":72,\"physical_caps_unchanged\":true,\"all_donors_global_active\":true,\"production_adopted\":false}\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=1;}Kokkos::finalize();return code;}
